const modeTasks=taskRows;taskRows=function(){let rows=modeTasks();return currentMode().hints?rows:rows.filter(t=>!t.label.startsWith('Explore:')&&!t.label.startsWith('Garden:'))};
const advancedEndings={grid:['Ending 25 · A city with its lights on','You isolate the circuit feeding the spare room. Along every street, the lamps brighten. Mother calls from a house with one fewer door.'],dawn:['Ending 26 · The first bus home','You sit beside the porter and wait until daylight. When the next bus arrives, the passengers are ordinary strangers. For once, nobody knows your name.'],witness:['Ending 27 · The witness','You watch the film, then tell the archivist exactly what you saw. This time, there is a witness outside the house. Mother can no longer be made to forget.'],keeper:['Ending 28 · Keep the door closed','You choose to remain, with a warning on the fuse box and the lantern beside the door. The house does not stop whispering. You learn when not to listen.']};
