const advancedCityVenue=cityVenue;cityVenue=function(id){let extra=id==='station'&&advancedEndingAllowed('dawn')?'dawn':id==='library'&&advancedEndingAllowed('witness')?'witness':null;if(!extra)return advancedCityVenue(id);modal(cityPlaces.find(p=>p.id===id).name,'Your discoveries offer a new way to finish the story.',[['Earlier choices',()=>advancedCityVenue(id)],[extra==='dawn'?'Wait for the first bus':'Give a witness statement',()=>ending(extra)],['Keep exploring',close]])};
